// EDIT: map each room_type to its public photo URLs
const roomType = ($('Execute Workflow Trigger').item.json.room_type || '').toLowerCase();
const photosByType = {
  'dorm': [
    'https://REPLACE_WITH_YOUR_IMAGE_HOST/dorm-1.jpg',
    'https://REPLACE_WITH_YOUR_IMAGE_HOST/dorm-2.jpg'
  ],
  'standard cottage': [
    'https://REPLACE_WITH_YOUR_IMAGE_HOST/standard-1.jpg',
    'https://REPLACE_WITH_YOUR_IMAGE_HOST/standard-2.jpg'
  ],
  'premium cottage': [
    'https://REPLACE_WITH_YOUR_IMAGE_HOST/premium-1.jpg',
    'https://REPLACE_WITH_YOUR_IMAGE_HOST/premium-2.jpg'
  ]
};
let urls = [];
for (const key of Object.keys(photosByType)) {
  if (roomType.includes(key.split(' ')[0])) { urls = photosByType[key]; break; }
}
if (urls.length === 0) urls = photosByType['dorm'];
return urls.map(url => ({ json: { to: $('Execute Workflow Trigger').item.json.to, url } }));

const input = $input.first().json;

const msg = input.messages?.[0];
const contact = input.contacts?.[0];

if (!msg) {
  throw new Error("No WhatsApp message found");
}

return [
  {
    json: {
      from: msg.from,
      text: msg.text?.body ?? "",
      messageType: msg.type,
      contactName: contact?.profile?.name ?? "",
      waMessageId: msg.id,
    },
  },
];
